it.each([false,true])('uses the accepted real HTTP rollback route and fresh history reconciliation after lost receipt=%s without another writer',async(loseReceipt)=>{
 const origin='https://portal.example.test',ownerToken='synthetic-http-rollback-owner';let current=U,writes=0,drop=loseReceipt;
 const history=vi.fn(async(actor:string,tenantId:string,flowId:string)=>{if(actor!==U||tenantId!==T||flowId!==F)throw new FlowError('FORBIDDEN');return PaidVersionHistory.parse({...rollbackHistory,versions:rollbackHistory.versions.map(version=>({...version,current:version.versionId===current}))});});
 const writer=vi.fn(async(actor:string,tenantId:string,flowId:string,input:{expectedCurrentVersionId:string;targetVersionId:string})=>{if(actor!==U||tenantId!==T||flowId!==F)throw new FlowError('FORBIDDEN');if(input.expectedCurrentVersionId!==current||input.targetVersionId!==S)throw new FlowError('CONFLICT');current=S;writes++;return PaidRollbackReceipt.parse(rollbackReceipt);});
 const server=createFlowHttpServer({repository:{call:vi.fn()},paidSimplePublication:true,paidRollback:writer,paidVersionHistory:history,ownerOrigins:[origin],customerOrigins:[publicationInput.checkoutOrigin],authenticateOwner:async token=>token===ownerToken?U:null});await new Promise<void>(r=>server.listen(0,'127.0.0.1',r));
 try{const address=server.address() as {port:number};const f=vi.fn<typeof fetch>(async(input,options)=>{const url=new URL(String(input));if(url.pathname==='/auth/v1/token')return json({access_token:ownerToken});if(url.pathname==='/auth/v1/user')return json({id:U});const response=await fetch('http://127.0.0.1:'+address.port+url.pathname+url.search,{...options,headers:{...options?.headers,Origin:origin}});if(url.pathname.endsWith('/rollback')&&response.ok&&drop){drop=false;await response.text();throw Error('Lost real HTTP rollback receipt');}return response;});const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},f);await c.signIn('owner@example.test','fixture');await c.paidSimpleVersionHistory(T,F);if(loseReceipt){await expect(c.rollbackPaidSimplePublication(T,F,rollbackInput)).rejects.toMatchObject({delivery:'unknown'});await c.paidSimpleVersionHistory(T,F);expect(c.paidSimpleRollbackState(T).phase).toBe('unknown');expect(await c.reconcilePaidSimpleRollback(T)).toEqual(rollbackReceipt);}else expect(await c.rollbackPaidSimplePublication(T,F,rollbackInput)).toEqual(rollbackReceipt);expect(c.paidSimpleRollbackState(T)).toMatchObject({phase:'verified',receipt:rollbackReceipt});expect(writes).toBe(1);expect(writer).toHaveBeenCalledExactlyOnceWith(U,T,F,rollbackInput);expect(f.mock.calls.slice(2).filter(([,options])=>options?.method==='POST')).toHaveLength(1);expect(history).toHaveBeenCalledWith(U,T,F);
 }finally{server.closeAllConnections();await new Promise<void>((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}
},15000);

