it.each([false,true])('uses accepted real business HTTP route and same-key unchanged-body replay after lost receipt=%s',async(loseReceipt)=>{
 const origin='https://portal.example.test',ownerToken='synthetic-http-business-owner';let stored:{body:string;profile:ReturnType<typeof BusinessProfileSchema.parse>}|undefined,writes=0,drop=loseReceipt;
 const creator=vi.fn(async(actor:string,input:CreateBusinessBody)=>{if(actor!==U)throw new FlowError('FORBIDDEN');const body=JSON.stringify(input);if(stored&&stored.body!==body)throw new FlowError('CONFLICT');if(!stored){writes++;stored={body,profile:BusinessProfileSchema.parse(businessReceipt)};}return stored.profile;});
 const server=createFlowHttpServer({repository:{call:vi.fn()},businessOnboarding:true,businessCreate:creator,businessProfile:async(actor,tenantId)=>{if(actor!==U)throw new FlowError('FORBIDDEN');if(tenantId!==S)throw new FlowError('NOT_AVAILABLE');return BusinessProfileSchema.parse(businessReceipt);},ownerOrigins:[origin],customerOrigins:[],authenticateOwner:async token=>token===ownerToken?U:null});await new Promise<void>(r=>server.listen(0,'127.0.0.1',r));
 try{const address=server.address() as {port:number};const f=vi.fn<typeof fetch>(async(input,options)=>{const url=new URL(String(input));if(url.pathname==='/auth/v1/token')return json({access_token:ownerToken});if(url.pathname==='/auth/v1/user')return json({id:U});if(url.pathname==='/rest/v1/tenant_members')return json(loseReceipt?(stored?[{tenant_id:S,role:'BUSINESS_OWNER'}]:[]):ownerMemberships);const response=await fetch('http://127.0.0.1:'+address.port+url.pathname+url.search,{...options,headers:{...options?.headers,Origin:origin}});if(url.pathname==='/api/businesses'&&response.ok&&drop){drop=false;await response.text();throw Error('Lost real HTTP business creation receipt');}return response;});const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},f);await c.signIn('owner@example.test','fixture');if(loseReceipt){await expect(c.createBusiness(businessInput)).rejects.toMatchObject({delivery:'unknown'});expect(await c.createBusiness(businessInput)).toEqual(businessReceipt);}else expect(await c.createBusiness(businessInput)).toEqual(businessReceipt);expect(writes).toBe(1);expect(creator).toHaveBeenCalledWith(U,businessInput);expect(await c.businessProfile(S)).toEqual({status:'initialized',profile:businessReceipt});expect(await c.businessProfile(T)).toEqual({status:'uninitialized',tenantId:T});const calls=f.mock.calls.filter(([url])=>String(url).endsWith('/api/businesses'));expect(calls).toHaveLength(loseReceipt?2:1);if(loseReceipt)expect(calls[0]?.[1]?.body).toBe(calls[1]?.[1]?.body);
 }finally{server.closeAllConnections();await new Promise<void>((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}
},15000);

